using System;using System.Collections.Generic;using System.Drawing;using System.IO;using System.Linq;using System.Net;using System.Net.Sockets;using System.Security.Cryptography;using System.Text;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;using System.Web.Script.Serialization;
public sealed class ChatAppearance {
 public string font="Arial",text="#f7f0ff",name="#c8a3ff",background="#251937";
 public int size=20,emote=30,limit=30,duration=0;public bool transparent=true,timestamps=true,platforms=true;
 public void Validate(){if(string.IsNullOrEmpty(font)||font.Length>80||!System.Text.RegularExpressions.Regex.IsMatch(font,@"^[\p{L}\p{N} _-]+$"))font="Arial";foreach(var field in new[]{"text","name","background"}){var info=GetType().GetField(field);if(!System.Text.RegularExpressions.Regex.IsMatch((string)info.GetValue(this)??"",@"^#[0-9a-fA-F]{6}$"))info.SetValue(this,field=="background"?"#251937":field=="name"?"#c8a3ff":"#f7f0ff");}size=Math.Max(12,Math.Min(40,size));emote=Math.Max(16,Math.Min(64,emote));limit=Math.Max(1,Math.Min(100,limit));duration=Math.Max(0,Math.Min(600,duration));}
}
public sealed class ObsSettings {public ChatAppearance style=new ChatAppearance();public string token="",sendToken="";public bool enabled;}
public sealed class ObsServer:IDisposable {
 readonly string sendToken;readonly Action<string> command;readonly TcpListener listener;readonly string token,host;readonly SemaphoreSlim slots=new SemaphoreSlim(16);readonly CancellationTokenSource stop=new CancellationTokenSource();
