 public ObsServer(int port,string key,Action<string> dispatch=null,string senderKey=null){sendToken=senderKey;command=dispatch;token=key;host="127.0.0.1:"+port;foreach(var name in new[]{"obs.html","obs.js","obs.css"})using(var source=typeof(ObsServer).Assembly.GetManifestResourceStream(name)){if(source==null)throw new IOException("OBS files are missing. Reinstall the app.");using(var data=new MemoryStream()){source.CopyTo(data);assets[name]=data.ToArray();}}listener=new TcpListener(IPAddress.Loopback,port);listener.Start(16);var task=Accept();}
 public void Publish(string value){lock(gate){if(value==json)return;json=value;using(var hash=SHA256.Create())tag="\""+Convert.ToBase64String(hash.ComputeHash(Encoding.UTF8.GetBytes(value)))+"\"";}}
 async Task Accept(){while(!stop.IsCancellationRequested){try{var client=await listener.AcceptTcpClientAsync();if(!slots.Wait(0)){client.Close();continue;}var task=Serve(client);}catch(ObjectDisposedException){break;}catch(SocketException){if(stop.IsCancellationRequested)break;}}}
 async Task Serve(TcpClient client){try{using(client)using(var stream=client.GetStream())using(var timeout=CancellationTokenSource.CreateLinkedTokenSource(stop.Token)){timeout.CancelAfter(55000);using(timeout.Token.Register(()=>client.Close())){var raw=new StringBuilder();var b=new byte[1];while(raw.Length<8192&&!raw.ToString().EndsWith("\r\n\r\n")){if(await stream.ReadAsync(b,0,1,timeout.Token)==0)return;raw.Append((char)b[0]);}if(!raw.ToString().EndsWith("\r\n\r\n"))return;var lines=raw.ToString().Split(new[]{"\r\n"},StringSplitOptions.None);var request=lines[0].Split(' ');var headers=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(string line in lines.Skip(1)){int index=line.IndexOf(':');if(index>0){string name=line.Substring(0,index);if(headers.ContainsKey(name))return;headers[name]=line.Substring(index+1).Trim();}}string value;int code=200;string type="text/plain",etag="";byte[] body=Encoding.UTF8.GetBytes("Not found");
 if(request.Length!=3||(request[0]!="GET"&&!(request[0]=="POST"&&((command!=null&&request[1]=="/command")||(sendToken!=null&&request[1]=="/chat-send")))))code=405;
 else if(!headers.TryGetValue("Host",out value)||value!=host||(headers.TryGetValue("Origin",out value)&&value!="http://"+host))code=403;
 else if(request[1]=="/command"&&command!=null&&request[0]=="POST"){int length;if(!headers.TryGetValue("Authorization",out value)||value!="Bearer "+token)code=401;else if(headers.ContainsKey("Transfer-Encoding")||!headers.TryGetValue("Content-Length",out value)||!int.TryParse(value,out length)||length<1||length>64)code=400;else{var payload=new byte[length];int offset=0;while(offset<length){int count=await stream.ReadAsync(payload,offset,length-offset,timeout.Token);if(count==0)return;offset+=count;}var name=Encoding.UTF8.GetString(payload);if(!new[]{"toggleSound","pauseRules","resumeRules","replay","showChat"}.Contains(name))code=400;else{command(name);body=Encoding.UTF8.GetBytes("Accepted");code=202;}}}
 else if(request[1]=="/chat-send"&&request[0]=="POST"&&sendToken!=null){int length;if(!headers.TryGetValue("Authorization",out value)||value!="Bearer "+sendToken)code=401;else if(headers.ContainsKey("Transfer-Encoding")||!headers.TryGetValue("Content-Length",out value)||!int.TryParse(value,out length)||length<1||length>4096)code=400;else{var payload=new byte[length];int offset=0;while(offset<length){int count=await stream.ReadAsync(payload,offset,length-offset,timeout.Token);if(count==0)return;offset+=count;}body=Encoding.UTF8.GetBytes(await ChatSend.Send(Encoding.UTF8.GetString(payload)));type="application/json";}}
