}
public partial class MainWindow {
 static int ObsPort {get{return IntegratedHost.Testing?28741:18741;}}ObsSettings obs=new ObsSettings();ObsServer obsServer;System.Windows.Forms.Timer obsTimer;Font chatFont;string obsError="";
 void InitObs(){InitPulse();try{obs=AccountStore.Read<ObsSettings>("obs-view")??new ObsSettings();}catch{obsError="Saved OBS preferences could not be unlocked.";}if(obs.style==null)obs.style=new ChatAppearance();obs.style.Validate();ApplyChatAppearance();obsTimer=new System.Windows.Forms.Timer{Interval=750};obsTimer.Tick+=delegate{PublishObs();};obsTimer.Start();Shown+=delegate{if(obs.enabled)try{StartObs();}catch(Exception e){obsError=e.Message;}};FormClosed+=delegate{obsTimer.Dispose();if(obsServer!=null)obsServer.Dispose();if(chatFont!=null)chatFont.Dispose();};}
 void SaveObs(){if(!IntegratedHost.Testing)AccountStore.Save("obs-view",obs);}
 void StartObs(){if(obsServer!=null)return;if(obsError!="")throw new IOException(obsError);if(!System.Text.RegularExpressions.Regex.IsMatch(obs.token??"","^[a-f0-9]{64}$")){var bytes=new byte[32];using(var rng=RandomNumberGenerator.Create())rng.GetBytes(bytes);obs.token=BitConverter.ToString(bytes).Replace("-","").ToLowerInvariant();}if(!System.Text.RegularExpressions.Regex.IsMatch(obs.sendToken??"","^[a-f0-9]{64}$")){var sendBytes=new byte[32];using(var rng=RandomNumberGenerator.Create())rng.GetBytes(sendBytes);obs.sendToken=BitConverter.ToString(sendBytes).Replace("-","").ToLowerInvariant();}obs.enabled=true;SaveObs();try{obsServer=new ObsServer(ObsPort,obs.token,null,obs.sendToken);PublishObs();}catch(SocketException){throw new IOException("The OBS port is busy. Close another copy of this app and try again.");}}
 void PublishObs(){PublishControls();if(obsServer==null)return;var messages=chatMessages.Skip(Math.Max(0,chatMessages.Count-100)).Select(a=>new{id=a.ChatId,name=a.Name,platform=a.Platform,received=a.ChatReceived,runs=a.Runs.Take(256).Select(r=>new{text=r.Text,url=r.Url}).ToArray()}).ToArray();obsServer.Publish(new JavaScriptSerializer{MaxJsonLength=8388608}.Serialize(new{style=obs.style,messages=messages,pulse=pulseEffect}));}
 int ChatHeaderHeight{get{return Math.Max(32,(chatFont??Font).Height+12);}}
 void ApplyChatAppearance(){obs.style.Validate();var old=chatFont;chatFont=new Font(obs.style.font,obs.style.size*72f/96f,FontStyle.Regular);if(chatList!=null){chatList.Font=chatFont;chatList.BackColor=ColorTranslator.FromHtml(obs.style.background);chatList.ForeColor=ColorTranslator.FromHtml(obs.style.text);RefreshChat();}if(old!=null)old.Dispose();PublishObs();}
